import styled from '@emotion/styled';
import BalancedChoices from 'assets/img/CategoryOverview/balanced_choices.png';
import BeerParticipation from 'assets/img/CategoryOverview/beer_participation.png';
import BeyondBeer from 'assets/img/CategoryOverview/beyond_beer.png';
import SuperiorCore from 'assets/img/CategoryOverview/core_superiority.png';
import LeadPremium from 'assets/img/CategoryOverview/lead_premium.png';
import { Card, Paragraph } from 'components/UI';
import { theme } from 'theme';

type CardWidth = 243 | 311;

type BackgroundImageVariant =
  | 'BeerParticipation'
  | 'BeyondBeer'
  | 'SuperiorCore'
  | 'BalancedChoices'
  | 'LeadPremium';

interface StyledCardProps {
  $width?: CardWidth;
}

export const StyledCard = styled(Card, {
  shouldForwardProp: (propName) => propName !== '$width',
})<StyledCardProps>(({ $width }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'flex-start',
  justifyContent: 'flex-start',
  padding: '18px 16px 16px',
  border: '1px solid rgba(0, 0, 0, 0.1)',
  ...($width === 243 && { width: '243px' }),
  ...($width === 311 && {
    width: '311px',
    paddingLeft: '36px',
  }),
}));

export const StyledHeader = styled.div({
  display: 'flex',
  justifyContent: 'flex-start',
  width: '100%',
  gap: '6px',
});

export const StyledHeadline = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '2px',
});

export const StyledMainContent = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '12px',
});

const backgroundImages: Record<BackgroundImageVariant, string> = {
  BeerParticipation: `url(${BeerParticipation})`,
  BeyondBeer: `url(${BeyondBeer})`,
  SuperiorCore: `url(${SuperiorCore})`,
  BalancedChoices: `url(${BalancedChoices})`,
  LeadPremium: `url(${LeadPremium})`,
};

interface StyledImageProps {
  $backgroundImage?: BackgroundImageVariant;
}

export const StyledImage = styled('div', {
  shouldForwardProp: (propName) => propName !== '$backgroundImage',
})<StyledImageProps>(({ $backgroundImage }) => ({
  minWidth: '80px',
  minHeight: '80px',
  margin: '0 auto',
  backgroundRepeat: 'no-repeat',
  backgroundSize: 'contain',
  ...($backgroundImage != null && {
    backgroundImage: backgroundImages[$backgroundImage],
  }),
}));

export const StyledIndicatorTitle = styled(Paragraph)({
  fontSize: '12px !important',
});

export const StyledNumbersInfo = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '12px',
});

export const StyledDetailedInfo = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '4px',
});

interface StyledNumberProps {
  $color?: 'up' | 'down';
}

export const StyledNumber = styled(Paragraph, {
  shouldForwardProp: (propName) => propName !== '$color',
})<StyledNumberProps>(({ $color }) => ({
  '&.up': {
    color: theme.colors.charts.txt.status.increase,
  },
  '&.down': {
    color: theme.colors.charts.txt.status.decrease,
  },
  ...($color === 'up' && {
    color: theme.colors.charts.txt.status.increase,
  }),
  ...($color === 'down' && {
    color: theme.colors.charts.txt.status.decrease,
  }),
}));
